def max_score(n, weights):
    weights.sort()
    return abs(weights[n-1] - weights[1]) + abs(weights[1] - weights[0])

def main():
    t = int(input())
    results = []
    for _ in range(t):
        n = int(input())
        weights = list(map(int, input().split()))
        results.append(max_score(n, weights))
    for result in results:
        print(result)

if __name__ == "__main__":
    main()
